class Checker:
    def check(self, isConnected, result):
        if not isinstance(result, int):
            return False
        n = len(isConnected)
        seen = [False] * n
        provinces = 0
        for i in range(n):
            if seen[i]:
                continue
            provinces += 1
            stack = [i]
            seen[i] = True
            while stack:
                u = stack.pop()
                row = isConnected[u]
                for v in range(n):
                    if row[v] and not seen[v]:
                        seen[v] = True
                        stack.append(v)
        return result == provinces

